import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import API from "../api";
import Navbar from "./Navbar";

const Profile = () => {
  const [user, setUser] = useState(null);
  const [jobs, setJobs] = useState([]);
  const navigate = useNavigate();

  const fetchProfile = async () => {
    try {
      const token = localStorage.getItem("access");
      const res = await API.get("/auth/profile/", { headers: { Authorization: `Bearer ${token}` } });
      setUser(res.data);

      // Fetch jobs created by recruiter
      if (res.data.User_Type === "Recruiter") {
        const jobsRes = await API.get("/job/JobList/", { headers: { Authorization: `Bearer ${token}` } });
        setJobs(jobsRes.data);
      }
    } catch (err) {
      console.error(err.response?.data);
      localStorage.clear();
      navigate("/login");
    }
  };

  useEffect(() => { fetchProfile(); }, []);

  const handleDelete = async (jobId) => {
    if (!window.confirm("Are you sure you want to delete this job?")) return;
    try {
      const token = localStorage.getItem("access");
      await API.delete(`/job/${jobId}/`, { headers: { Authorization: `Bearer ${token}` } });
      setJobs(jobs.filter(job => job.id !== jobId));
      alert("Job deleted successfully!");
    } catch (err) {
      console.error(err.response?.data);
      alert("Failed to delete job!");
    }
  };

  if (!user) return <p>Loading...</p>;

  return (
    <>
      <Navbar />
      <div className="container mt-5">
        <div className="card shadow p-4 mb-4" style={{ maxWidth: "600px", margin: "auto" }}>
          <h2 className="text-primary mb-4">Profile</h2>
          <p><strong>Username:</strong> {user.username}</p>
          <p><strong>Email:</strong> {user.email}</p>
          <p><strong>User Type:</strong> {user.User_Type}</p>
        </div>

        {user.User_Type === "Recruiter" && (
          <div className="card shadow p-4">
            <h3 className="text-primary mb-4">My Jobs</h3>
            {jobs.length === 0 ? <p>No jobs created yet.</p> : (
              <div className="table-responsive">
                <table className="table table-striped">
                  <thead>
                    <tr>
                      <th>#</th>
                      <th>Title</th>
                      <th>Type</th>
                      <th>Description</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {jobs.map((job, index) => (
                      <tr key={job.id}>
                        <td>{index + 1}</td>
                        <td>{job.Job_Title}</td>
                        <td>{job.Job_Type}</td>
                        <td>{job.Job_Description}</td>
                        <td>
                          <button className="btn btn-sm btn-info me-2" onClick={() => navigate(`/job/${job.id}`)}>View</button>
                          <button className="btn btn-sm btn-warning me-2" onClick={() => navigate(`/edit-job/${job.id}`)}>Edit</button>
                          <button className="btn btn-sm btn-danger" onClick={() => handleDelete(job.id)}>Delete</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}
      </div>
    </>
  );
};

export default Profile;
